<script setup lang="ts">
import LiveMechanicsPanel from './LiveMechanicsPanel.vue';
import {isExtendedPlayAction} from '../../../api/src/rules/extended-actions';
import {explicitPower} from '../../../api/src/rules/live-power-registry';
import AngelusDetailCards from './builder/AngelusDetailCards.vue';
import DaemonDetailCards from './builder/DaemonDetailCards.vue';
import MageTechniqueCards from './builder/MageTechniqueCards.vue';
import {hourlyRecovery,naniteStatus} from '../../../api/src/rules/live-mechanics';
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {playPortrait} from '../../../api/src/character-appearances';
import {truthPowers,powerAllowed,formAvailable} from '../../../api/src/rules/play-truth';
import {api,ApiError} from '../lib/api';
import {blankPlayState,playProfile,type PlayState} from '../../../api/src/rules/play-state';
import type {CharacterDataV2} from '../types/character';
import type {CharacterSheet} from '../lib/character-sheet';
const emit=defineEmits<{ready:[];changed:[]}>();
const props=defineProps<{id:string;data:CharacterDataV2;sheet:CharacterSheet;canEdit:boolean;combatMode?:boolean}>();
const state=ref<PlayState>(blankPlayState()),version=ref(0),loaded=ref(false),busy=ref(false),error=ref(''),notice=ref(''),dirty=ref(false);
const tab=ref('jets'),skillQuery=ref(''),edge=ref(0),useEdge=ref(false),escapeEvent=ref<string|null>(null);
const tabs=[['jets','Jets & compétences'],['states','États & PV'],['truth','Vérité & pouvoirs'],['rest','Repos'],['equipment','Équipement'],['rules','Mes règles'],['history','Historique']];
const clean=(s:string)=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');
const campaignId=ref<string|null>(null),combat=ref<any>(null);
const inCombat=computed(()=>props.combatMode??(campaignId.value?!!combat.value?.active:state.value.initiative!==null));
const events=ref<any[]>([]),lastRoll=ref<any>(null),amount=ref(1),days=ref(3),prolonged=ref(false);
const bonusLabel=ref(''),bonusSkill=ref('athletisme'),bonusAmount=ref(1),bonusTruth=ref(false);
const canManageMechanics=ref(false),serverReality=ref<any>(null);
const profile=computed(()=>({...playProfile(props.data,state.value),reality:serverReality.value}));
function actionAllowed(action:string){return props.canEdit||canManageMechanics.value&&isExtendedPlayAction(action);}
const portrait=computed(()=>playPortrait(props.data,state.value));
const powerList=computed(()=>truthPowers(props.data)),powerId=ref(''),powerCost=ref(0),powerDuration=ref(0),powerSkill=ref(''),powerAmount=ref(0),powerNote=ref('');
const chosenPower=computed(()=>powerList.value.find(p=>p.id===powerId.value));
const chosenRegistered=computed(()=>{const power=explicitPower(powerId.value);return power?.nature===props.data.truth.nature?power:null;});
const genericPowerAvailable=computed(()=>chosenPower.value?.execution==='assisted'&&!chosenRegistered.value);
function powerRouteHelp(){const route=chosenPower.value?.execution;return chosenRegistered.value?'Utilise les capacités préparées ci-dessous pour leurs coûts, quotas et effets.':({defense:'Cette capacité se choisit directement dans la défense contre une attaque ; coût, bonus et usage sont gérés au lancer.',heal:'Utilise le Cycle de réparation dans la rubrique États & PV.',passive:'La Réserve nanitique intervient automatiquement au premier soin réel éligible du scénario.',vampire:'Utilise les commandes Stase & Sang ci-dessous ou la capacité liée à ton attaque.',nature:'Utilise les ressources et commandes de nature ci-dessous ; leurs coûts et leurs préparations sont suivis.'} as Record<string,string>)[route??'']??'Consulte la commande dédiée à cette capacité.';}
const recoveryHours=ref(1),regenerable=ref(false);
const hourlyRate=computed(()=>hourlyRecovery(props.data,state.value)),nanites=computed(()=>naniteStatus(props.data,state.value));
const form=ref('hybrid'),exhaustion=ref('');
const isShifter=computed(()=>['garou','khinae'].includes(String(props.data.truth.nature)));
const stressNames=['Neutre (Normal)','Tendu','Paniqué'];
const groups=computed(()=>profile.value.attributes.map(a=>({...a,skills:profile.value.skills.filter(s=>s.attribute===a.id&&(!skillQuery.value||clean(s.name).includes(clean(skillQuery.value))))})).filter(g=>g.skills.length));
const endpoint=computed(()=>`/api/characters/${props.id}/play`);
let timer:ReturnType<typeof setInterval>|undefined,alive=true;
let pending:{requestId:string;version:number;action:string;[key:string]:unknown}|null=null;
const mechanicsMessages:Record<string,string>={neuro_restart_outside_combat:'Termine le combat avant le redémarrage Neuro.',neuro_safe_restart_required:'Confirme le redémarrage sûr, après la fin du combat Neuro.',mageius_unavailable:'Le Mageius est indisponible : vérifie la Révélation, le sommeil et le contrecoup.',nature_settings_mj_only:'Ces conditions sont fixées par le MJ.',invalid_investment:'Les PA investis dépassent le coût ou les PA disponibles.',spell_not_ready:'La préparation du sort demande encore des PA.',power_not_ready:'La préparation de cette capacité demande encore des PA.',preparation_already_active:'Une préparation est déjà en cours. Termine-la ou abandonne-la.',preparation_interrupted:'Cette préparation a été interrompue. Prépare à nouveau la capacité.',aureole_disconnected:'Le lien divin est indisponible ; le MJ peut préciser cette condition.',aura_full:'La réserve d’Aura est déjà pleine.',insufficient_aura:'Pas assez d’Aura disponible.',divine_favor_unavailable:'La Faveur est indisponible : vérifie la Révélation, le lieu de résonance et les usages.',favor_context_required:'Précise une action relevant réellement de ta Facette.',vampire_revelation_required:'Le Vampire doit être Révélé pour utiliser cette commande.',stasis_required:'La récupération exige la Stase.',cannot_leave_stasis:'Récupère des PV positifs avant de quitter la Stase.',regenerable_hours_required:'Déclare le temps écoulé et confirme que les blessures sont régénérables.',power_context_required:'Confirme les conditions réelles de cette capacité.',power_already_active:'Cette capacité est déjà préparée ou active.',power_skill_unavailable:'Cette compétence ne correspond pas à la capacité.',combat_required:'Cette commande exige un combat et une initiative déjà lancée.',cannot_act:'Le personnage est incapable d’agir dans son état actuel.',initiative_required:'Lance l’initiative avant cette action de combat.',not_enough_pa:'Pas assez de PA disponibles.',out_of_combat:'Ce personnage est hors des tours de combat.',adrenaline_unavailable:'L’adrénaline est indisponible : vérifie l’implant actif, le quota et le combat.',effect_requires_manager:'Le retrait de cet effet demande un arbitrage du MJ.',invalid_neuro_load:'Vérifie les programmes possédés, l’interface et la capacité Neuro.',nature_spell_unavailable:'Cette nature ne peut pas préparer ce type de sort.',nature_action_unavailable:'Cette action de nature est indisponible : vérifie la Révélation, la conscience et les ressources.',cannot_react:'Le personnage ne peut pas réagir dans son état actuel.',actor_unavailable:'Le personnage ne peut pas agir : vérifie ses blessures, sa conscience et sa place dans le combat.',non_owner_action:'Cette commande est réservée au joueur qui contrôle le personnage.',spell_not_prepared:'Prépare un sort avant de le modifier ou de le lancer.',spectrum_not_prepared:'Prépare un Spectre avant de le modifier ou de le lancer.',power_not_prepared:'Aucune capacité de nature ne se trouve en préparation.',mage_rest_unavailable:'Le repos du Mage exige un round entier sans Mageius et aucune préparation en cours.',backlash_not_pending:'Aucun Revers du Mageius ne reste à résoudre.',nature_roll_required:'Le jet de cette capacité doit être résolu par la table. Actualise et réessaie la commande.',nature_power_unavailable:'Cette capacité est indisponible : vérifie son acquisition, sa Révélation et ses prérequis.',invalid_spell:'Vérifie la portée, l’Amplitude et la canalisation du sort.',spell_amplitude_unavailable:'Cette Amplitude dépasse la maîtrise disponible.',force_requires_owned_affinity:'Il faut posséder cette Affinité pour forcer sa Maîtrise ou son Amplitude.',invalid_superior_will:'Forcer exige le palier immédiatement supérieur à ta maîtrise.',mandatory_channel_missing:'Ajoute la canalisation requise pour cette difficulté.',spectrum_unavailable:'Ce Spectre exige l’état Révélé et une Affinité possédée.',spectrum_cannot_force:'Les Spectres ne permettent pas de forcer la Maîtrise ou l’Amplitude.',invalid_nature_settings:'Vérifie les conditions de nature déclarées par le MJ.',invalid_aura:'La réserve d’Aura doit rester entre zéro et son maximum.',aura_fill_outside_combat:'Prépare la réserve d’Aura hors combat.',invalid_aura_spend:'Choisis une quantité d’Aura disponible conforme à cette protection.',egide_not_applicable:'L’Égide protège contre les dégâts occultes uniquement.',offering_unavailable:'L’Offrande exige des PV disponibles et une réserve d’Aura incomplète.',blade_already_active:'La Lame céleste est déjà incarnée.',blade_unavailable:'La Lame céleste exige la Révélation, de l’Aura et les PV à réserver.',blade_not_active:'Aucune Lame céleste n’est actuellement incarnée.',favor_skill_required:'Choisis la compétence bénéficiaire de la Faveur.',no_anchor:'Aucun ancrage sanguin ne reste disponible.',no_death_anchor:'La restauration exige un ancrage et un Vampire ayant atteint son seuil de mort.',ritual_conditions_required:'Déclare le temps du rituel ; pour la restauration, au moins 24 heures, un corps réparable et un praticien sont requis.',anchor_exists:'Un ancrage sanguin est déjà préparé.',predation_required:'Cette capacité exige une Prédation réellement résolue pendant cette scène.',invalid_weakness:'Précise la faiblesse concernée par cette capacité.',already_applied:'Cet état est déjà appliqué.',neuro_program_unavailable:'Ce programme Neuro est indisponible ou ne fait pas partie des programmes possédés.',neuro_unavailable:'Le Neurodive exige une interface compatible et un accès disponible.',neuro_capacity_exceeded:'Le nombre de programmes dépasse la capacité de chargement.',neuro_load_unchanged:'Ces programmes sont déjà chargés.',magazine_requires_manager:'Le joueur déclare son chargeur hors combat ; pendant le combat, seul le MJ peut le corriger.',weapon_charge_unavailable:'Cette arme possédée ne dispose pas de chargeur suivi.',invalid_ammo_count:'Vérifie le nombre de charges et la réserve de munitions.',ammunition_confirmation_required:'Confirme que des munitions compatibles sont disponibles pour la recharge.',insufficient_ammunition:'Pas assez de munitions disponibles pour cette action.',magazine_full:'Le chargeur est déjà plein.'};
function message(cause:unknown){const code=cause instanceof Error?cause.message:'';if(mechanicsMessages[code])return mechanicsMessages[code];return cause instanceof ApiError&&cause.status===409?'L’état a changé dans un autre onglet. Actualise avant de réessayer.':({finish_combat_first:'Termine le combat avant de changer de scène ou de scénario.',use_dedicated_action:'Utilise la commande de défense ou de soin dédiée à cette capacité.',hourly_recovery_unavailable:'Récupération horaire indisponible : hors combat, vivant, en humain révélé ou animal.',nanite_cycle_unavailable:'Cycle indisponible : vérifie ton talent, tes blessures, ta conscience et ton essaim.',invalid_hourly_recovery:'Indique le nombre d’heures et confirme les blessures régénérables.',no_wounds:'Aucune blessure à soigner.',insufficient_edge:'Tu n’as plus d’Edge disponible.',edge_already_used:'Un Edge a déjà été utilisé pour ce jet ou cette conséquence.',edge_roll_resolved:'Ce jet a déjà été résolu : son résultat ne peut plus être modifié.',edge_consequence_unavailable:'Aucune conséquence mortelle actuelle ne correspond à cette demande.',initiative_already_rolled:'Ton initiative est déjà fixée pour ce combat.',participant_out:'Le MJ a sorti ce personnage des tours.',campaign_combat_mj_only:'Le MJ contrôle le début, la fin et les rounds du combat depuis la page En jeu de la campagne.',form_unavailable:'Cette forme est indisponible (Sang, blessures ou Mue en cours).',mue_exhaustion_required:'Résous le test d’épuisement puis indique son résultat.',mue_blocked:'Mue bloquée jusqu’à la prochaine scène.',insufficient_pa:'Pas assez de PA.',power_already_used:'Cette capacité a déjà été utilisée sur cette période.',power_unavailable:'Capacité indisponible dans cet état ou déjà active.',combat_not_started:'Commence un combat en lançant l’initiative.',rest_requires_positive_hp:'À 0 PV ou moins, stabilise puis soigne avant le repos.',character_dead:'Le seuil de mort est atteint : les soins ordinaires ne suffisent plus.',cannot_stabilize:'La stabilisation concerne uniquement un personnage agonisant vivant.'} as Record<string,string>)[cause instanceof Error?cause.message:'']??'Action non confirmée. Réessaie la même action pour vérifier son enregistrement.';}
async function load(){
  if(busy.value||dirty.value||!alive)return;
  try{const r=await api<{state:PlayState;version:number;events:any[];combat?:any;campaignId?:string;edge?:number;escapeEvent?:string|null;profile?:any;canManageMechanics?:boolean}>(endpoint.value);if(!alive||busy.value||dirty.value)return;const first=!loaded.value;canManageMechanics.value=r.canManageMechanics===true;serverReality.value=r.profile?.reality??null;campaignId.value=r.campaignId??null;combat.value=r.combat??null;edge.value=r.edge??0;escapeEvent.value=r.escapeEvent??null;state.value=r.state;version.value=r.version;events.value=r.events;lastRoll.value=r.events.find((e:any)=>e.payload.dice)??null;loaded.value=true;error.value='';if(first)emit('ready');}catch(cause){if(alive){canManageMechanics.value=false;error.value=message(cause);}}
}
async function perform(action:string,extra:Record<string,unknown>={}){
  if(busy.value||!loaded.value||!actionAllowed(action))return;
  if(dirty.value&&action!=='save'&&props.canEdit){await save();if(dirty.value||error.value)return;}
  if(pending&&pending.action!==action){error.value='Réessaie l’action non confirmée avant d’en effectuer une autre.';return;}
  pending??={requestId:crypto.randomUUID(),version:version.value,action,...extra};
  busy.value=true;error.value='';notice.value='';
  try{
    const r=await api<any>(endpoint.value,{method:'POST',body:JSON.stringify(pending)});
    pending=null;
    if(!alive)return;
    dirty.value=false;if(action==='roll')useEdge.value=false;
    if(r.state){state.value=r.state;serverReality.value=r.profile?.reality??serverReality.value;version.value=r.version;events.value=[r.event,...events.value].slice(0,30);if(r.event.payload.dice)lastRoll.value=r.event;notice.value=r.event.payload.recovered!==undefined?`${r.event.payload.recovered} PV récupérés.`:'Enregistré.';}
    busy.value=false;emit('changed');await load();
  }catch(cause){if(alive){error.value=message(cause);if(cause instanceof ApiError&&cause.status<500){pending=null;if(cause.status===409){dirty.value=false;busy.value=false;await load();}}}}
  finally{busy.value=false;}
}
function save(){return perform('save',{state:JSON.parse(JSON.stringify(state.value))});}
function addBonus(){if(!bonusLabel.value.trim())return;state.value.bonuses.push({id:crypto.randomUUID(),label:bonusLabel.value.trim(),skill:bonusSkill.value,amount:bonusAmount.value,truth:bonusTruth.value,enabled:true});bonusLabel.value='';dirty.value=true;}
function toggleAutomatic(id:string,enabled:boolean){state.value.disabled=enabled?state.value.disabled.filter(x=>x!==id):[...state.value.disabled,id];dirty.value=true;}
function toggleContext(id:string,enabled:boolean){state.value.contexts=enabled?[...state.value.contexts,id]:state.value.contexts.filter(x=>x!==id);dirty.value=true;}
const sourceOptions=computed(()=>[...props.sheet.realityTalents.map(s=>({name:s.name,truth:false})),...props.sheet.inventory.map(s=>({name:s.name,truth:s.group?.startsWith('Objet de Vérité')??false})),...props.sheet.truthTalents.map(s=>({name:s.name,truth:true}))]);
function sourceChanged(){bonusTruth.value=sourceOptions.value.find(s=>s.name===bonusLabel.value)?.truth??false;}
onMounted(()=>{void load();timer=setInterval(()=>{if(document.visibilityState==='visible')void load();},5000);});
onUnmounted(()=>{alive=false;clearInterval(timer);});
</script>
<template>
<section class="play-panel" aria-label="Personnage en jeu">
  <header><img v-if="portrait" :src="portrait" :alt="sheet.name" style="width:72px;height:96px;object-fit:cover;border-radius:6px" /><div><p class="eyebrow">EN JEU</p><h2>{{ sheet.name }}</h2></div><a class="ghost" :href="`/characters/${id}/play`" target="_blank" rel="noopener">Ouvrir dans un onglet dédié ↗</a></header>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <p v-if="!loaded">Chargement de l’état en jeu…</p>
  <template v-else>
    <div class="play-vitals"><strong>Edge {{edge}} / 8</strong><strong>{{ profile.hp }} / {{ profile.healingMaximum }} PV</strong><span v-if="profile.healingMaximum<profile.derived.pvMax">Maximum de base {{profile.derived.pvMax}} · {{profile.derived.pvMax-profile.healingMaximum}} PV réservés</span><strong>{{ profile.health }}</strong><span>{{ stressNames[profile.stress] }}</span><span v-if="inCombat">{{ profile.pa }} PA · Round {{ state.round }}</span><span v-if="inCombat&&state.initiative!==null">Initiative du combat : {{ state.initiative }} · {{ state.paPerRound }} PA par round</span></div>
    <div v-if="inCombat&&campaignId&&state.initiative===null&&combat?.participating!==false" class="initiative-call" role="status"><strong>Le combat commence : lance ton initiative.</strong><button :disabled="busy||!canEdit" @click="perform('initiative',useEdge?{edge:true}:{})">◈ Lancer mon initiative</button><label class="check"><input v-model="useEdge" type="checkbox" :disabled="busy||!canEdit||edge<1" /> Forcer le Destin · 1 Edge</label><p>Un seul jet pour tout le combat ; les PA reviennent à chaque round.</p></div>
    <p v-if="canManageMechanics&&!canEdit" class="manager-play-notice">MJ : tu peux suivre les ressources et utiliser leurs commandes. Les réglages ordinaires et les jets du personnage restent réservés à son joueur.</p>
    <nav class="play-tabs" aria-label="Rubriques de la fiche en jeu"><button v-for="[key,label] in tabs" :key="key" :aria-pressed="tab===key" @click="tab=key">{{label}}</button></nav>
    <p v-if="dirty" class="unsaved">Modifications en attente <button :disabled="busy||!canEdit" @click="save">Enregistrer les modifications</button></p>
    <div v-if="escapeEvent&&canEdit" class="escape-edge"><strong>Conséquence mortelle</strong><p>1 Edge permet de survivre. Les autres conséquences restent à décider avec le MJ ; le personnage reste agonisant.</p><button :disabled="busy||edge<1" @click="perform('edge-escape',{eventId:escapeEvent})">Échapper au Destin · 1 Edge</button></div>
    <LiveMechanicsPanel v-show="['truth','states','rest'].includes(tab)" :data="data" :state="state" :profile="profile" :can-edit="canEdit||canManageMechanics" :manager="canManageMechanics" :busy="busy" :in-combat="inCombat" @action="perform" />
    <fieldset v-show="tab==='states'" :disabled="busy||!canEdit">
      <legend>États et ressources</legend>
      <div class="play-fields">
        <label>Révélation<select v-model="state.revelation" @change="dirty=true;save()"><option value="v">Voilé</option><option value="sr">Semi-révélé</option><option value="r">Révélé</option></select></label>
        <label class="check"><input v-model="state.unconscious" type="checkbox" @change="dirty=true;save()" /> Inconscient / incapable de réagir</label><label v-if="nanites.cycle||nanites.reserve" class="check"><input v-model="state.swarmFunctional" type="checkbox" @change="dirty=true;save()" /> Essaim nanitique fonctionnel</label><label>Stress indépendant des blessures<select v-model.number="state.stress" @change="dirty=true"><option :value="0">Neutre (Normal)</option><option :value="1">Tendu</option><option :value="2">Paniqué</option></select></label>
        <label v-if="inCombat">PA restants<input type="number" min="0" :max="profile.hp<=0?1:data.truth.nature==='vampire'?6:5" v-model.number="state.pa" @input="dirty=true" /></label>
        <label v-if="inCombat">Round<input type="number" min="1" max="100000" v-model.number="state.round" :disabled="!!campaignId" @input="dirty=true" /></label>
      </div>
      <label v-for="bonus in profile.attributeBonuses" :key="bonus.id" class="check"><input type="checkbox" :checked="bonus.enabled" :disabled="bonus.id.startsWith('nature-')" @change="toggleAutomatic(bonus.id,($event.target as HTMLInputElement).checked)" />{{ bonus.label }} +{{ bonus.amount }}<em v-if="bonus.truth&&state.revelation==='v'"> — Vérité inactive</em></label>
      <label v-for="bonus in profile.mechanics" :key="bonus.id" class="check"><input type="checkbox" :checked="bonus.enabled" @change="toggleAutomatic(bonus.id,($event.target as HTMLInputElement).checked)" />{{ bonus.label }}</label>
      <p>Le Stress effectif tient compte des blessures. Chaque capacité respecte son accès Voilé, Semi-révélé ou Révélé. Les bonus manuels marqués Vérité exigent l’état Révélé.</p>
      <label class="check"><input type="checkbox" v-model="state.share" @change="dirty=true" /> Montrer mon portrait, mon nom, mon occupation, ma Sphère et mon état général aux joueurs de ma campagne.</label>
      <button :disabled="!dirty" @click="save">Enregistrer les états et bonus{{ dirty?' *':'' }}</button>
    </fieldset>
    <fieldset v-show="tab==='truth'" v-if="isShifter" :disabled="busy||!canEdit"><legend>Transformation · Garou / Khinae</legend><p>Forme actuelle : {{state.form==='hybrid'?'Hybride':state.form==='animal'?'Animale':'Humaine'}} · {{state.mueCount??0}} Mue(s) depuis le repos.</p><p v-if="state.muePending">Mue en cours : achèvement au round {{state.muePending}}. Le PA supplémentaire arrive au round suivant l’achèvement.</p><div class="play-fields"><label>Forme souhaitée<select v-model="form" aria-label="Forme souhaitée"><option v-for="[id,label] in [['human','Humain révélé'],['animal','Animal · 1 PA en combat'],['hybrid','Hybride · un round complet']]" :key="id" :value="id" :disabled="!formAvailable(data,id as 'human'|'animal'|'hybrid')">{{label}}</option></select></label><label v-if="form==='hybrid'&&(state.mueCount??0)>0">Résultat du test d’épuisement<select v-model="exhaustion" aria-label="Résultat du test d’épuisement"><option value="">À résoudre avec le MJ</option><option value="success">Réussite / exemption applicable</option><option value="force">Échec simple : forcer pour 3 PV irréductibles</option><option value="narrative-failure">Échec narratif : blocage pour la scène</option></select></label><button :disabled="!!state.muePending" @click="perform('form',{form,exhaustion})">Changer de forme</button><label class="check"><input v-model="state.inWater" type="checkbox" @change="dirty=true;save()" /> Dans l’eau (Lignées aquatiques)</label></div><p v-if="form==='hybrid'">Épuisement : 1re Mue automatique ; 2e difficulté 15 ; 3e 18 ; 4e 21 ; 5e et suivantes 25. Les exceptions et tests se résolvent avec le MJ ; la Mue ne soigne pas.</p><p v-if="profile.body">DGT naturels {{profile.body.damage}} · Armure corporelle {{profile.body.armor}} · Pugilat +{{profile.body.pugilat}} · Régénération {{profile.body.regeneration}} PV/round.</p><button v-if="profile.body?.regeneration" :disabled="!!state.powerUses?.['round:regeneration']" @click="perform('regenerate')">Appliquer la régénération du round (blessures régénérables)</button><p v-for="constraint in profile.body?.constraints" :key="constraint">{{constraint}}</p></fieldset>
    <fieldset v-show="tab==='truth'" v-if="powerList.length" :disabled="busy||!canEdit"><legend>Capacités de Vérité</legend><div class="play-fields"><label>Capacité<select v-model="powerId" aria-label="Capacité de Vérité"><option value="">Choisir une capacité possédée…</option><option v-for="p in powerList" :key="p.id" :value="p.id">{{p.name}} · {{p.access}}</option></select></label></div><template v-if="chosenPower"><p>{{chosenPower.activation}}</p><p style="white-space:pre-line">{{chosenPower.text}}</p><p v-if="!powerAllowed(chosenPower,state.revelation)">Révélation requise : {{chosenPower.stage==='sr'?'Semi-révélé ou Révélé':'Révélé'}}.</p><p v-if="!genericPowerAvailable">{{powerRouteHelp()}}</p><div v-if="genericPowerAvailable" class="play-fields"><label>Coût en PA<input v-if="chosenPower.cost===null" v-model.number="powerCost" type="number" min="0" max="20" /><strong v-else>{{chosenPower.cost}}</strong></label><label>Durée en rounds (0 : fin manuelle / scène)<input v-model.number="powerDuration" type="number" min="0" max="1000" /></label><label>Compétence affectée si applicable<select v-model="powerSkill"><option value="">Aucune / effet narratif</option><option v-for="s in profile.skills" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Bonus applicable selon la règle<input v-model.number="powerAmount" type="number" min="0" max="100" /></label><label>Cible / condition / ressources particulières<input v-model="powerNote" maxlength="500" /></label></div><p v-if="genericPowerAvailable">Confirme les conditions du texte avant d’activer. Les PA sont déduits en combat ; le bonus de compétence choisi s’applique pendant la durée indiquée, sans cumuler des bonus équivalents. Les effets sur une autre cible et les ressources particulières restent à résoudre avec le MJ.</p><button v-if="genericPowerAvailable" :disabled="!powerAllowed(chosenPower,state.revelation)" @click="perform('power',{powerId,enabled:true,paCost:chosenPower.cost??powerCost,duration:powerDuration,skill:powerSkill,amount:powerAmount,note:powerNote})">Activer la capacité</button></template><article v-for="p in state.powers??[]" :key="p.id"><strong>{{powerList.find(r=>r.id===p.id)?.name??p.id}}</strong> · {{p.until===null?'Fin manuelle / scène':'Jusqu’au round '+p.until}}<p>{{p.note}}</p><button @click="perform('power',{powerId:p.id,enabled:false})">Terminer cet effet</button></article><button v-if="!campaignId" :disabled="inCombat" @click="perform('scene')">Nouvelle scène : terminer les effets et renouveler les usages de scène</button><button v-if="!campaignId" :disabled="inCombat" @click="perform('scenario')">Nouveau scénario : renouveler les usages</button><p v-if="campaignId">Les nouvelles scènes et scénarios sont déclarés par le MJ depuis la table. Un nouveau combat ou une nouvelle séance ne renouvelle pas ces usages.</p><button v-if="!campaignId&&state.initiative!==null" @click="perform('end-combat')">Terminer le combat</button></fieldset>
    <fieldset v-show="tab==='states'" :disabled="busy||!canEdit"><legend>Blessures, soins et combat</legend><div class="play-fields"><label>PV à retirer (dégâts nets) ou soigner<input v-model.number="amount" type="number" min="1" max="10000" /></label><button @click="perform('damage',{amount})">Subir les dégâts</button><button @click="perform('heal',{amount})">Recevoir les soins</button><button v-if="profile.hp<=0&&profile.hp>profile.derived.death&&!state.stabilized" @click="perform('stabilize')">Stabiliser après réussite du soin</button><button v-if="!campaignId" @click="perform('initiative')">◈ Nouveau combat : initiative</button><button v-if="!campaignId" :disabled="state.initiative===null&&!state.muePending" @click="perform('round')">Round suivant</button></div><p v-if="campaignId"><a :href="`/campaigns/${campaignId}/play`">Table de la campagne · combat et rounds dirigés par le MJ ↗</a></p><p>L’initiative est conservée pendant tout le combat. Chaque nouveau round restitue les PA du combat, avec un plafond de 1 PA à 0 PV ou moins (Agonisant ou Stabilisé). Déduis les PA dépensés dans le compteur ; relance l’initiative au début du prochain combat.</p></fieldset>
    <fieldset v-show="tab==='states'" v-if="nanites.cycle||nanites.reserve" :disabled="busy||!canEdit"><legend>Soins nanitiques</legend><p v-if="nanites.reserve">Réserve nanitique : {{nanites.reserveUsed?'consommée pour ce scénario':'disponible · +3 PV au premier soin réel reçu'}}. Aucun déclenchement sur le repos, la régénération ou le Cycle.</p><p v-if="!nanites.functional">Essaim non fonctionnel : soins nanitiques indisponibles.</p><button v-if="nanites.cycle" :disabled="nanites.cycleUsed||!nanites.functional||state.unconscious||profile.hp<=0||profile.hp>=profile.healingMaximum||(inCombat&&(state.initiative===null||profile.pa<1))" @click="perform('nanite-cycle')">Cycle de réparation · +{{Math.max(0,Math.min(6,profile.healingMaximum-profile.hp))}} PV · {{inCombat?'1 PA · ':''}}{{nanites.cycleUsed?'utilisé':'1/scénario'}}</button><p>Il faut être conscient et vivant. Le Cycle ne déclenche pas la Réserve ; ses usages persistent entre combats et séances.</p></fieldset>
    <fieldset v-show="tab==='rest'" v-if="hourlyRate" :disabled="busy||!canEdit||inCombat"><legend>Récupération Garou / Khinae · hors combat</legend><p>{{hourlyRate}} PV par heure écoulée, en humain révélé ou animal. Déclare le temps réellement passé ; n’applique pas aussi le repos quotidien pour la même période.</p><div class="play-fields"><label>Heures écoulées<input v-model.number="recoveryHours" type="number" min="1" max="8760" /></label><label class="check"><input v-model="regenerable" type="checkbox" /> Les blessures soignées sont régénérables</label><strong>+{{Math.max(0,Math.min(profile.healingMaximum-profile.hp,recoveryHours*hourlyRate))}} PV</strong><button :disabled="!regenerable||profile.hp<=profile.derived.death" @click="perform('recover-hours',{hours:recoveryHours,regenerable})">Appliquer la récupération horaire</button></div></fieldset>
    <section v-show="tab==='equipment'" aria-label="Équipement possédé"><h3>Mon équipement & mes possessions</h3><p>Train de vie : <strong>{{sheet.lifestyle}}</strong> · Compte {{sheet.account}} $ · Espèces {{sheet.cash}} $</p><article v-for="item in sheet.inventory" :key="item.id" class="rule-card"><h4>{{item.name}}</h4><small>{{item.group}}</small><p>{{item.detail}}</p></article><p v-if="!sheet.inventory.length">Aucun équipement enregistré.</p></section>
    <section v-show="tab==='rules'" aria-label="Règles de mon personnage"><h3>Réalité & Vérité · mes règles</h3><AngelusDetailCards :entries="sheet.angelusDetails??[]" :aura="sheet.angelusAura" /><DaemonDetailCards :entries="sheet.daemonDetails??[]" /><MageTechniqueCards :entries="sheet.mageTechniques??[]" /><p>Les calculs des jets détaillent les effets automatiques et les conditions activées. Consulte ici le texte complet des effets possédés ; active une capacité depuis « Vérité & pouvoirs » ou prépare un modificateur dans « Jets & compétences ».</p><template v-for="group in [{name:'Talents de Réalité',items:sheet.realityTalents},{name:'Talents de Vérité',items:sheet.truthTalents},{name:'Traits de nature',items:sheet.truthFreeTraits??[]},{name:'Règles dérivées',items:sheet.talentRules??[]},{name:'Désavantages',items:sheet.disadvantages}]" :key="group.name"><h4>{{group.name}}</h4><details v-for="item in group.items" :key="item.id"><summary>{{item.name}}</summary><p class="rule-text">{{item.effectDetails??item.detail}}</p><a v-if="item.compendiumId" :href="`/compendium?article=${encodeURIComponent(item.compendiumId)}`" target="_blank" rel="noopener">Règle du Compendium ↗</a></details></template></section>
    <fieldset v-show="tab==='rest'" :disabled="busy||!canEdit"><legend>Récupération entre les scènes</legend><div class="play-fields"><label>Jours de repos<input v-model.number="days" type="number" min="1" max="365" /></label><label class="check"><input v-model="prolonged" type="checkbox" /> Soins prolongés</label><strong>{{ Math.max(0,Math.min(profile.healingMaximum-profile.hp,days*(prolonged?profile.recovery.prolonged:profile.recovery.normal))) }} PV à récupérer</strong><button @click="perform('rest',{days,prolonged})">Appliquer ce repos</button></div><p>{{ profile.recovery.normal }} PV/jour · {{ profile.recovery.prolonged }} PV/jour avec soins prolongés. Les soins particuliers sont à appliquer avec « Recevoir les soins ».</p></fieldset>
    <details v-show="tab==='jets'"><summary>Configurer un bonus de pouvoir, d’augmentation ou de situation</summary><fieldset :disabled="busy||!canEdit"><legend>Bonus supplémentaire explicite</legend><p>Les bonus préparés apparaissent sous les compétences concernées. Ce réglage permet d’ajouter un effet particulier ou un ajustement de situation convenu avec le MJ.</p><div class="play-fields"><label>Source<select v-model="bonusLabel" @change="sourceChanged"><option value="">Choisir…</option><option v-for="s in sourceOptions" :key="s.name" :value="s.name">{{ s.name }}</option><option value="Situation (MJ)">Situation (MJ)</option></select></label><label>Compétence<select v-model="bonusSkill"><option v-for="s in profile.skills" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Bonus / malus<input type="number" min="-100" max="100" v-model.number="bonusAmount" /></label><label class="check"><input type="checkbox" v-model="bonusTruth" /> Vérité : Révélé seulement</label><button @click="addBonus">Ajouter</button></div></fieldset></details>
    <div v-if="lastRoll" :key="lastRoll.id" class="roll-result" role="status"><strong>{{ lastRoll.payload.label }}</strong><span v-for="(die,i) in lastRoll.payload.dice" :key="i" class="die" :style="{'animation-delay':`${Number(i)*.45}s`}">{{ die }}</span><span v-if="lastRoll.payload.edgeForced">Forcer le Destin · 1 Edge</span><span v-else-if="lastRoll.payload.exploded">Explosion !</span><strong>{{ lastRoll.payload.modifier }} + {{ lastRoll.payload.dice.join(' + ') }} = {{ lastRoll.payload.total }}</strong><strong v-if="lastRoll.payload.narrativeFailure" class="failure">Échec narratif, quel que soit le total.</strong><button v-if="canEdit&&!lastRoll.payload.edgeForced&&['roll','initiative'].includes(lastRoll.kind)" :disabled="busy||edge<1" @click="perform('edge-force',{eventId:lastRoll.id})">Forcer ce jet · 1 Edge</button></div>
    <div v-show="tab==='jets'" class="skill-tools"><label>Retrouver une compétence<input v-model="skillQuery" type="search" placeholder="Athlétisme, Tir, Perception…" /></label><label class="check"><input v-model="useEdge" type="checkbox" :disabled="busy||!canEdit||edge<1" /> Forcer le Destin au prochain jet · 1 Edge · dé remplacé par 20</label><small>L’Edge est conservé entre les séances. Un seul Edge par jet ou conséquence.</small></div>
    <p v-show="tab==='jets'">Neutre : échec sur 1, explosion sur 10. Tendu : échec sur 1–2, explosion sur 9–10. Paniqué : échec sur 1–3, explosion sur 10. Le deuxième dé n’explose jamais. Pour les bonus préparés équivalents, seul le meilleur s’applique ; les ajustements manuels s’ajoutent.</p>
    <p v-if="tab==='jets'&&!groups.length">Aucune compétence ne correspond à « {{skillQuery}} ». <button @click="skillQuery=''">Effacer la recherche</button></p>
    <details v-show="tab==='jets'" v-for="group in groups" :key="group.id" open><summary>{{ group.name }} · {{ group.value }}</summary><article v-for="skill in group.skills" :key="skill.id" class="skill-roll"><div class="skill-line"><strong>{{ skill.name }}</strong><span>{{ skill.attributeValue }} + {{ skill.rank }}<template v-if="skill.bonus"> {{ skill.bonus>=0?'+':'−' }} {{ Math.abs(skill.bonus) }}</template> = <b>{{ skill.total }}</b></span><button :disabled="busy||!canEdit" :aria-label="`Lancer le d10 pour ${skill.name}`" @click="perform('roll',{skill:skill.id,...(useEdge?{edge:true}:{})})">◈ d10</button></div><small>{{ group.name }} + rang de compétence + bonus actifs</small>
      <label v-for="bonus in skill.automatic" :key="bonus.id" class="check"><input type="checkbox" :checked="bonus.enabled" :disabled="busy||!canEdit" @change="toggleAutomatic(bonus.id,($event.target as HTMLInputElement).checked)" />{{ bonus.label }} +{{ bonus.amount }}</label>
      <label v-for="bonus in skill.contexts" :key="bonus.id" class="check"><input type="checkbox" :checked="bonus.enabled" :disabled="busy||!canEdit" @change="toggleContext(bonus.id,($event.target as HTMLInputElement).checked)" />{{ bonus.label }} +{{ bonus.bonus }} (meilleur bonus de Talent applicable)</label>
      <label v-for="bonus in skill.prepared" :key="bonus.id" class="check"><input type="checkbox" :checked="bonus.enabled" :disabled="busy||!canEdit" @change="toggleContext(bonus.id,($event.target as HTMLInputElement).checked)" />{{ bonus.label }} +{{ bonus.bonus }}<em v-if="bonus.truth&&state.revelation!=='r'"> — Vérité inactive</em></label>
      <div v-for="bonus in state.bonuses.filter(b=>b.skill===skill.id)" :key="bonus.id" class="custom-bonus"><label class="check"><input type="checkbox" v-model="bonus.enabled" :disabled="busy||!canEdit" @change="dirty=true" />{{ bonus.label }} {{ bonus.amount>=0?'+':'' }}{{ bonus.amount }} {{ bonus.truth?'· Vérité':'' }}<em v-if="bonus.truth&&state.revelation!=='r'"> — inactif</em></label><button :disabled="busy||!canEdit" aria-label="Retirer ce bonus" @click="state.bonuses=state.bonuses.filter(b=>b.id!==bonus.id);dirty=true">Retirer</button></div>
    </article></details>
    <details v-show="tab==='history'" open><summary>Historique partagé avec le MJ</summary><article v-for="event in events" :key="event.id" class="event"><small>{{ new Date(event.createdAt).toLocaleString('fr-FR') }}</small><strong>{{ event.payload.label }}</strong><span v-if="event.payload.dice">{{ event.payload.modifier }} + {{ event.payload.dice.join(' + ') }} = {{ event.payload.total }}{{ event.payload.narrativeFailure?' · ÉCHEC NARRATIF':'' }}</span><button v-if="canEdit&&event.payload.dice&&!event.payload.edgeForced&&['roll','initiative'].includes(event.kind)" :disabled="busy||edge<1" @click="perform('edge-force',{eventId:event.id})">Forcer ce jet · 1 Edge</button><span v-if="event.payload.before!==undefined">{{ event.payload.before }} → {{ event.payload.after }} PV</span><span v-if="event.payload.recovered!==undefined">+{{ event.payload.recovered }} PV en {{ event.payload.days }} jour(s)</span></article></details>
  </template>
</section>
</template>
<style scoped>.manager-play-notice{padding:12px;border:1px solid #ad8d62;border-radius:6px;background:#292324;line-height:1.5}.initiative-call{padding:16px;border:2px solid #b7efff;border-radius:8px;display:flex;flex-wrap:wrap;gap:12px;align-items:center}.rule-card{border-bottom:1px solid #355267;padding:12px}.rule-card p,.rule-text{white-space:pre-line;line-height:1.6}
.play-tabs{display:flex;flex-wrap:wrap;gap:8px}.play-tabs button[aria-pressed=true]{background:#bcefff;color:#092130}.skill-tools label{display:grid;gap:8px}.escape-edge{border:1px solid #ffb4b4;padding:12px}.play-panel{display:grid;gap:18px;padding:20px;background:#0d1b2b;border:1px solid #355267;border-radius:10px;margin:20px 0;color:#e6eef8;overflow-wrap:anywhere}.play-panel header,.play-vitals,.skill-line,.custom-bonus{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap}.play-panel h2{margin:4px 0}.play-panel fieldset{border:1px solid #355267;border-radius:8px;padding:16px;min-width:0}.play-fields{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.play-fields label{display:grid;gap:6px;flex:1;min-width:120px}.play-panel .check{display:flex;gap:8px;align-items:center;margin:10px 0}.play-panel input:not([type=checkbox]),.play-panel select{width:100%;min-width:0;padding:10px;background:#071320;color:inherit;border:1px solid #526c80;border-radius:4px}.play-panel button,.play-panel a{min-height:44px;padding:10px 14px;border:1px solid #52758b;background:#102b3e;color:#c3f4ff;border-radius:5px;cursor:pointer}.play-panel button:disabled{opacity:.5;cursor:default}.play-panel summary{padding:12px;cursor:pointer;background:#142839}.skill-roll{padding:15px;border-bottom:1px solid #355267}.skill-roll small{color:#acc1d0}.play-vitals{padding:15px;border:1px solid #78bcd0}.play-vitals strong{font-size:1.25rem}.event{display:flex;flex-wrap:wrap;gap:10px;padding:12px;border-bottom:1px solid #355267}.event small{color:#acc1d0}.roll-result{display:flex;flex-wrap:wrap;gap:16px;align-items:center;border:1px solid #8cdcfa;padding:16px}.die{display:grid;place-items:center;width:48px;height:48px;background:#bcefff;color:#092130;font-weight:bold;font-size:22px;clip-path:polygon(50% 0,100% 30%,85% 85%,50% 100%,15% 85%,0 30%);animation:roll .45s both}.failure{color:#ffb4b4}@keyframes roll{from{transform:rotate(-180deg) scale(.5);opacity:0}to{transform:none;opacity:1}}@media(prefers-reduced-motion:reduce){.die{animation:none}}@media(max-width:500px){.play-panel{padding:12px}.play-panel fieldset{padding:10px}.skill-line>span{flex-basis:100%}}
</style>
